import{_ as t,o as a,c as l,a4 as d}from"./chunks/framework.BUqnS5H7.js";const g=JSON.parse('{"title":"Kafka 参数速查","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/reference/parameters.md","filePath":"kafka/reference/parameters.md"}'),r={name:"kafka/reference/parameters.md"};function s(i,e,c,n,o,f){return a(),l("div",null,[...e[0]||(e[0]=[d(`<h1 id="kafka-参数速查" tabindex="-1" data-src-line="1" data-src-file="kafka/reference/parameters.md">Kafka 参数速查 <a class="header-anchor" href="#kafka-参数速查" aria-label="Permalink to &quot;Kafka 参数速查&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/reference/parameters.md"><p data-src-line="3" data-src-file="kafka/reference/parameters.md">本表列出常用参数的官方默认值与生产选取建议。所有默认值来自 <a href="https://kafka.apache.org/documentation/#configuration" target="_blank" rel="noreferrer">Kafka 官方配置文档</a>，版本相关的差异会在备注中说明。推荐值只写有明确理由的取值，不写「随手拍」的区间。</p></blockquote><h2 id="_1-broker-配置" tabindex="-1" data-src-line="5" data-src-file="kafka/reference/parameters.md">1. Broker 配置 <a class="header-anchor" href="#_1-broker-配置" aria-label="Permalink to &quot;1. Broker 配置&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="kafka/reference/parameters.md"><tr data-src-line="7" data-src-file="kafka/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">官方默认</th><th style="text-align:left;">生产建议</th><th style="text-align:left;">说明与版本</th></tr></thead><tbody data-src-line="9" data-src-file="kafka/reference/parameters.md"><tr data-src-line="9" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>broker.id</code></td><td style="text-align:left;"><code>-1</code>（自动）</td><td style="text-align:left;">显式设置为唯一整数</td><td style="text-align:left;">自动生成从 <code>reserved.broker.max.id + 1</code> 起分配</td></tr><tr data-src-line="10" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>num.partitions</code></td><td style="text-align:left;"><code>1</code></td><td style="text-align:left;">按吞吐容量规划</td><td style="text-align:left;">自动创建 Topic 时的分区数；生产 Topic 建议显式指定 <code>--partitions</code></td></tr><tr data-src-line="11" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>default.replication.factor</code></td><td style="text-align:left;"><code>1</code></td><td style="text-align:left;"><code>3</code></td><td style="text-align:left;">自动创建 Topic 的副本因子；生产必须提升</td></tr><tr data-src-line="12" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>min.insync.replicas</code></td><td style="text-align:left;"><code>1</code></td><td style="text-align:left;"><code>2</code></td><td style="text-align:left;">仅当 <code>acks=all</code> 时生效；与 RF=3 搭配</td></tr><tr data-src-line="13" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>unclean.leader.election.enable</code></td><td style="text-align:left;"><code>false</code>（0.11+）</td><td style="text-align:left;">保持 <code>false</code></td><td style="text-align:left;">允许 = 换取可用性、丢数据</td></tr><tr data-src-line="14" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>auto.leader.rebalance.enable</code></td><td style="text-align:left;"><code>true</code></td><td style="text-align:left;"><code>true</code></td><td style="text-align:left;">自动把 Leader 迁回 preferred replica</td></tr><tr data-src-line="15" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>log.retention.hours</code></td><td style="text-align:left;"><code>168</code>（7 天）</td><td style="text-align:left;">按业务保留窗口调整</td><td style="text-align:left;">也可用 <code>log.retention.ms</code> / <code>log.retention.bytes</code></td></tr><tr data-src-line="16" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>log.retention.bytes</code></td><td style="text-align:left;"><code>-1</code>（不限制）</td><td style="text-align:left;">与磁盘容量匹配</td><td style="text-align:left;">按分区计算</td></tr><tr data-src-line="17" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>log.segment.bytes</code></td><td style="text-align:left;"><code>1073741824</code>（1 GiB）</td><td style="text-align:left;">默认足够</td><td style="text-align:left;">段过小 → 段文件过多；过大 → 清理粒度粗</td></tr><tr data-src-line="18" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>log.index.interval.bytes</code></td><td style="text-align:left;"><code>4096</code></td><td style="text-align:left;">默认</td><td style="text-align:left;">稀疏索引密度，详见 <a href="./chapter-02-log-segment.html">日志分段与索引</a></td></tr><tr data-src-line="19" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>message.max.bytes</code></td><td style="text-align:left;"><code>1048588</code>（≈ 1 MiB）</td><td style="text-align:left;">显式设置，且与生产者 <code>max.request.size</code>、消费者 <code>fetch.max.bytes</code> 一致</td><td style="text-align:left;">三处不匹配会导致上游能发、下游拿不到</td></tr><tr data-src-line="20" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>replica.lag.time.max.ms</code></td><td style="text-align:left;"><code>30000</code>（2.5+）／<code>10000</code>（2.4 及以前，<a href="https://cwiki.apache.org/confluence/display/KAFKA/KIP-537" target="_blank" rel="noreferrer">KIP-537</a>）</td><td style="text-align:left;">保持默认</td><td style="text-align:left;">调小易触发 spurious ISR 收缩</td></tr><tr data-src-line="21" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>num.replica.fetchers</code></td><td style="text-align:left;"><code>1</code></td><td style="text-align:left;"><code>2</code>–<code>4</code>（磁盘/网卡富余时）</td><td style="text-align:left;">提升 Follower 并行度</td></tr></tbody></table><h2 id="_2-producer-配置" tabindex="-1" data-src-line="23" data-src-file="kafka/reference/parameters.md">2. Producer 配置 <a class="header-anchor" href="#_2-producer-配置" aria-label="Permalink to &quot;2. Producer 配置&quot;">​</a></h2><table tabindex="0"><thead data-src-line="25" data-src-file="kafka/reference/parameters.md"><tr data-src-line="25" data-src-file="kafka/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">官方默认</th><th style="text-align:left;">生产建议</th><th style="text-align:left;">说明与版本</th></tr></thead><tbody data-src-line="27" data-src-file="kafka/reference/parameters.md"><tr data-src-line="27" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>acks</code></td><td style="text-align:left;"><code>all</code>（3.0+，<a href="https://cwiki.apache.org/confluence/display/KAFKA/KIP-679" target="_blank" rel="noreferrer">KIP-679</a>）／<code>1</code>（3.0 前）</td><td style="text-align:left;"><code>all</code></td><td style="text-align:left;">与 <code>min.insync.replicas</code> 配合才有意义</td></tr><tr data-src-line="28" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>enable.idempotence</code></td><td style="text-align:left;"><code>true</code>（3.0+，<a href="https://cwiki.apache.org/confluence/display/KAFKA/KIP-679" target="_blank" rel="noreferrer">KIP-679</a>）／<code>false</code>（3.0 前）</td><td style="text-align:left;"><code>true</code></td><td style="text-align:left;">开启会强制 <code>acks=all</code>、<code>retries=MAX_VALUE</code>、<code>max.in.flight ≤ 5</code></td></tr><tr data-src-line="29" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>retries</code></td><td style="text-align:left;"><code>Integer.MAX_VALUE</code>（幂等开启时强制）</td><td style="text-align:left;">保持默认</td><td style="text-align:left;">启用幂等后 Kafka 自动设为 MAX_VALUE；关闭幂等时也应保持较大值靠 <code>delivery.timeout.ms</code> 兜底</td></tr><tr data-src-line="30" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>delivery.timeout.ms</code></td><td style="text-align:left;"><code>120000</code>（2 min）</td><td style="text-align:left;">与业务超时对齐</td><td style="text-align:left;">覆盖 <code>linger.ms + request.timeout.ms + retry</code> 总时长</td></tr><tr data-src-line="31" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>max.in.flight.requests.per.connection</code></td><td style="text-align:left;"><code>5</code></td><td style="text-align:left;">幂等模式下 <code>≤ 5</code></td><td style="text-align:left;">关闭幂等时 <code>&gt;1</code> 有乱序风险</td></tr><tr data-src-line="32" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>batch.size</code></td><td style="text-align:left;"><code>16384</code>（16 KiB）</td><td style="text-align:left;"><code>32768</code>–<code>131072</code></td><td style="text-align:left;">提高批量效率；配合 <code>linger.ms</code></td></tr><tr data-src-line="33" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>linger.ms</code></td><td style="text-align:left;"><code>0</code></td><td style="text-align:left;"><code>5</code>–<code>20</code></td><td style="text-align:left;">允许攒批的等待时长</td></tr><tr data-src-line="34" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>buffer.memory</code></td><td style="text-align:left;"><code>33554432</code>（32 MiB）</td><td style="text-align:left;">视吞吐上调</td><td style="text-align:left;">缓冲不足时 send 会阻塞或抛异常</td></tr><tr data-src-line="35" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>compression.type</code></td><td style="text-align:left;"><code>none</code></td><td style="text-align:left;"><code>lz4</code> 或 <code>zstd</code></td><td style="text-align:left;">生产者压缩，broker 存原样透传</td></tr></tbody></table><h2 id="_3-consumer-配置" tabindex="-1" data-src-line="37" data-src-file="kafka/reference/parameters.md">3. Consumer 配置 <a class="header-anchor" href="#_3-consumer-配置" aria-label="Permalink to &quot;3. Consumer 配置&quot;">​</a></h2><table tabindex="0"><thead data-src-line="39" data-src-file="kafka/reference/parameters.md"><tr data-src-line="39" data-src-file="kafka/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">官方默认</th><th style="text-align:left;">生产建议</th><th style="text-align:left;">说明与版本</th></tr></thead><tbody data-src-line="41" data-src-file="kafka/reference/parameters.md"><tr data-src-line="41" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>group.id</code></td><td style="text-align:left;">无</td><td style="text-align:left;">必填</td><td style="text-align:left;">唯一标识消费者组</td></tr><tr data-src-line="42" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>auto.offset.reset</code></td><td style="text-align:left;"><code>latest</code></td><td style="text-align:left;">视业务选 <code>earliest</code> 或 <code>latest</code></td><td style="text-align:left;">无 committed offset 时的行为</td></tr><tr data-src-line="43" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>enable.auto.commit</code></td><td style="text-align:left;"><code>true</code></td><td style="text-align:left;"><code>false</code>（业务处理完再手动提交）</td><td style="text-align:left;">详见 <a href="./../02-core/chapter-03-consumer-group.html">Offset 管理</a></td></tr><tr data-src-line="44" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>max.poll.records</code></td><td style="text-align:left;"><code>500</code></td><td style="text-align:left;">保持默认；处理耗时长时下调</td><td style="text-align:left;">与 <code>max.poll.interval.ms</code> 联动</td></tr><tr data-src-line="45" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>max.poll.interval.ms</code></td><td style="text-align:left;"><code>300000</code>（5 min）</td><td style="text-align:left;">&gt; 最坏批处理时长</td><td style="text-align:left;">超过则被踢出组触发 rebalance</td></tr><tr data-src-line="46" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>session.timeout.ms</code></td><td style="text-align:left;"><code>45000</code>（3.0+，<a href="https://cwiki.apache.org/confluence/display/KAFKA/KIP-735" target="_blank" rel="noreferrer">KIP-735</a>）／<code>10000</code>（3.0 前）</td><td style="text-align:left;">保持默认</td><td style="text-align:left;">太小则 GC 抖动就触发 rebalance</td></tr><tr data-src-line="47" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>heartbeat.interval.ms</code></td><td style="text-align:left;"><code>3000</code></td><td style="text-align:left;"><code>session.timeout.ms / 3</code></td><td style="text-align:left;">心跳线程独立于 poll</td></tr><tr data-src-line="48" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>fetch.min.bytes</code></td><td style="text-align:left;"><code>1</code></td><td style="text-align:left;">高吞吐时可上调</td><td style="text-align:left;">broker 攒够字节再返回</td></tr><tr data-src-line="49" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>fetch.max.wait.ms</code></td><td style="text-align:left;"><code>500</code></td><td style="text-align:left;">默认</td><td style="text-align:left;">与 <code>fetch.min.bytes</code> 配合</td></tr><tr data-src-line="50" data-src-file="kafka/reference/parameters.md"><td style="text-align:left;"><code>isolation.level</code></td><td style="text-align:left;"><code>read_uncommitted</code></td><td style="text-align:left;">事务场景 <code>read_committed</code></td><td style="text-align:left;">详见 <a href="./../03-reliability/chapter-04-exactly-once.html">Exactly Once 语义</a></td></tr></tbody></table><h2 id="_4-jvm-与-os" tabindex="-1" data-src-line="52" data-src-file="kafka/reference/parameters.md">4. JVM 与 OS <a class="header-anchor" href="#_4-jvm-与-os" aria-label="Permalink to &quot;4. JVM 与 OS&quot;">​</a></h2><p data-src-line="54" data-src-file="kafka/reference/parameters.md">Kafka Broker 的堆调优核心是<strong>留足内存给 Page Cache</strong>，详细推理见 <a href="./../04-performance/chapter-01-why-kafka-is-fast.html">Page Cache 与零拷贝</a> §4。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Broker JVM（32 GiB 物理内存示例）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KAFKA_HEAP_OPTS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-Xms6g -Xmx6g&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KAFKA_JVM_PERFORMANCE_OPTS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-XX:+UseG1GC -XX:MaxGCPauseMillis=20 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  -XX:InitiatingHeapOccupancyPercent=35&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># OS 层</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># /etc/sysctl.d/99-kafka.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vm.swappiness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # 尽量避免 Page Cache 被换出</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vm.max_map_count</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=1000000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 分区规模大时必须调高（默认 65530 会被打穿）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ulimit</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> soft nofile 100000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> hard nofile 100000</span></span></code></pre></div><blockquote data-src-line="71" data-src-file="kafka/reference/parameters.md"><p data-src-line="71" data-src-file="kafka/reference/parameters.md">Xmx 与 Xms 相等避免堆动态扩缩；32 GiB 物理内存里堆保持 6 GiB 左右，剩余全部让 OS 用作 Page Cache。这套推荐来自 <a href="https://kafka.apache.org/documentation/#hardware" target="_blank" rel="noreferrer">Kafka 官方 §Hardware and OS</a> 与 <a href="https://kafka.apache.org/documentation/#maximizingefficiency" target="_blank" rel="noreferrer">Kafka 官方 §Performance</a>。</p></blockquote>`,12)])])}const p=t(r,[["render",s]]);export{g as __pageData,p as default};
